# Generate a cubic P with one real root alpha in (p, p+1), complex conjugate roots beta, gamma with |beta|<1
# and a second cubic Q with a positive integer root R>alpha.
import math

# Helper: discriminant of x^3 - p x^2 - q x - r
def disc(p, q, r):
    return -18*p*q*r - 4*(p**3)*r + (p**2)*(q**2) + 4*(q**3) - 27*(r**2)

# Choose parameters for P
attempts = 0
while True:
    attempts += 1
    if attempts > 1000:
        raise RuntimeError("Failed to generate suitable cubic parameters")
    p = rng.randint(6, 11)
    q = rng.randint(1, p-2)
    r = rng.randint(1, p-2)  # ensure r < p so r/alpha<1
    # Ensure alpha in (p, p+1): P(p) < 0 and P(p+1) > 0
    Pp = p**3 - p*p**2 - q*p - r  # = -q p - r < 0 automatically
    Pp1 = (p+1)**3 - p*(p+1)**2 - q*(p+1) - r  # simplifies to (p+1)^2 - q(p+1) - r
    if not (Pp < 0 and Pp1 > 0):
        continue
    # Ensure one real root: discriminant negative
    if disc(p, q, r) >= 0:
        continue
    # Choose R > p+1 so that the smallest positive real root comes from P
    R = rng.randint(p+2, p+8)
    # Bound |beta| <= sqrt(r/alpha) < sqrt(r/p)
    t_upper = math.sqrt(r / float(p))
    # Choose k so that 2*|beta|^k < 1/4 ensuring s_k is the nearest integer to alpha^k
    k = rng.randint(32, 60)
    guard = 0
    while 2.0 * (t_upper ** k) > 0.25:
        k += 1
        guard += 1
        if k > 200 or guard > 200:
            break
    if 2.0 * (t_upper ** k) > 0.25:
        continue
    # Choose prime-power residue system
    primes_pool = [5, 7, 11, 13, 17, 19, 23]
    t_mods = rng.randint(3, 4)
    primes = rng.sample(primes_pool, t_mods)
    exponents = [1] * t_mods
    # Ensure at least one prime power with exponent > 1 for added difficulty
    idx_e = rng.randrange(t_mods)
    exponents[idx_e] = rng.choice([2, 2])  # keep modulus manageable
    degrees = []
    for i in range(t_mods):
        pi = primes[i]
        ei = exponents[i]
        order_i = (pi - 1) * (pi ** (ei - 1))
        if i == idx_e:
            # Force gcd(d, order) > 1 by choosing d multiple of pi when ei>1
            d_i = pi
        else:
            # Prefer a divisor of (pi-1) occasionally to ensure nontrivial gcd
            divisors = [d for d in range(2, pi - 1) if (pi - 1) % d == 0]
            if divisors and rng.random() < 0.6:
                d_i = rng.choice(divisors)
            else:
                d_i = rng.randint(2, max(3, pi - 1))
        degrees.append(d_i)
    # Compute modulus L = prod pi^ei and ensure it's manageable for enumeration in verifier
    L = 1
    for i in range(t_mods):
        L *= primes[i] ** exponents[i]
    if L > 200000:
        continue
    # Compute s_k modulo L via recurrence s_n = p s_{n-1} + q s_{n-2} + r s_{n-3}
    s0 = 3 % L
    s1 = p % L
    s2 = (p * p + 2 * q) % L
    a3, a2, a1 = s0, s1, s2
    for n in range(3, k + 1):
        cur = (p * a1 + q * a2 + r * a3) % L
        a3, a2, a1 = a2, a1, cur
    N_mod = a1  # s_k modulo L
    # Choose base_offset as an integer multiple of L to ensure several full blocks
    blocks_count = rng.randint(2, 4)
    base_offset = blocks_count * L
    # Build display for rules
    rules_display = "; ".join([f"mod {primes[i]}^{exponents[i]}: non-zero {degrees[i]}-th power residues" for i in range(t_mods)])
    return {
        'poly_p': p,
        'poly_q': q,
        'poly_r': r,
        'poly_R': R,
        'exp_k': k,
        'modulus': L,
        'base_offset': base_offset,
        'rules_display': rules_display,
        # Raw lists for verifier
        'primes': primes,
        'exponents': exponents,
        'degrees': degrees,
        'blocks_count': blocks_count,
    }

