    # Not enough moduli
    return (False, None)
# Check primes are odd and >= 5
for pi in primes:
    if pi < 5:
        return (False, None)
    # primality check (simple)
    for t in range(2, int(math.sqrt(pi)) + 1):
        if pi % t == 0:
            return (False, None)
# Check L matches product of prime powers
L_check = 1
for i in range(len(primes)):
    ei = exponents[i]
    if ei < 1:
        return (False, None)
    L_check *= (primes[i] ** ei)
if L_check != L:
    return (False, None)

# Check base_offset is multiple of L and blocks_count matches
if base_offset % L != 0:
    return (False, None)
if blocks_count != base_offset // L:
    return (False, None)
if blocks_count < 2:
    # Enforce difficulty: at least two full blocks
    return (False, None)

# Validate the cubic P properties: one real root in (p,p+1), conjugate roots magnitude < 1
def disc(p, q, r):
    return -18*p*q*r - 4*(p**3)*r + (p**2)*(q**2) + 4*(q**3) - 27*(r**2)
Pp = p**3 - p*p**2 - q*p - r
Pp1 = (p+1)**3 - p*(p+1)**2 - q*(p+1) - r
