    return (False, None)
if 2.0 * (t_upper ** k) > 0.4:
    return (False, None)

# Compute s_k modulo L via recurrence
s0 = 3 % L
s1 = p % L
s2 = (p * p + 2 * q) % L
a3, a2, a1 = s0, s1, s2
for n in range(3, k + 1):
    cur = (p * a1 + q * a2 + r * a3) % L
    a3, a2, a1 = a2, a1, cur
N = a1  # nearest-integer remainder due to rounding proof
M = base_offset + N

# Counting qualified IDs:
# For each modulus p_i^{e_i}, unit group order = (p_i - 1) * p_i^{e_i - 1}.
# Non-zero d_i-th residues form a subgroup image of size order_i / gcd(d_i, order_i).
# By CRT, number per full block of length L equals product over i of that size.
allowed_per_block = 1
moduli = []
ords = []
gs = []
for i in range(len(primes)):
    pi = primes[i]
    ei = exponents[i]
    di = degrees[i]
    mod_i = pi ** ei
    ord_i = (pi - 1) * (pi ** (ei - 1))
    g_i = gcd(di, ord_i)
    moduli.append(mod_i)
    ords.append(ord_i)
    gs.append(g_i)
    allowed_per_block *= (ord_i // g_i)
full_blocks = M // L
rem = M % L
count_full = full_blocks * allowed_per_block

# Count the remainder [1..rem] by direct test using group criterion: y in (G)^d iff y^{ord/g} ≡ 1 mod p^e and y is a unit
def passes_all(m):
    for i in range(len(primes)):
        pi = primes[i]
        mod_i = moduli[i]
        ord_i = ords[i]
        g_i = gs[i]
        y = m % mod_i
        if y % pi == 0:
            return False  # not a unit -> remainder zero or divisible by p
        # d-th power residue test in cyclic group
        if pow(y, ord_i // g_i, mod_i) != 1:
            return False
    return True

leftover_count = 0
# rem can be zero; if so, no leftover.
for m in range(1, rem + 1):
    if passes_all(m):
        leftover_count += 1

answer = count_full + leftover_count
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

